{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "Dynamic SOQL with user input",
      "severity": "Medium",
      "file": "TaskSearchController.cls",
      "lines": "8",
      "explanation": "The method concatenates the caller-provided subjectFilter into a dynamic SOQL string. Even though escapeSingleQuotes is used, dynamic queries with user input are still considered an injection risk because they bypass the parser’s safety checks and can be abused if future changes remove the escaping or add other unescaped inputs.",
      "remediation": "Rewrite the query to use a bind variable or static SOQL, e.g. `SELECT Id, Subject, Status, ActivityDate FROM Task WHERE Subject LIKE :('%' + subjectFilter + '%') WITH USER_MODE LIMIT 200`. This eliminates the need for string concatenation and fully protects against injection."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via unescaped user input",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "6",
      "explanation": "The method concatenates the caller-provided searchKey directly into a dynamic SOQL string without escaping or binding, allowing an attacker to inject arbitrary SOQL clauses.",
      "remediation": "Use a bind variable or escape the input: e.g., SELECT Id, Name, Industry FROM Account WHERE Name LIKE :('%' + String.escapeSingleQuotes(searchKey) + '%') LIMIT 50; or use Database.queryWithBinds with an allow‑list for field names."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Missing FLS enforcement on SOSL query",
      "severity": "Medium",
      "file": "InvoiceSearchController.cls",
      "lines": "5-7",
      "explanation": "The SOSL query returns fields without enforcing field‑level security, allowing users to see data they may not have permission to view.",
      "remediation": "Add WITH SECURITY_ENFORCED to the SOSL query or use Security.stripInaccessible to filter fields based on the current user's FLS."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic WHERE Clause",
      "severity": "Medium",
      "file": "ReportFilterController.cls",
      "lines": "7-15",
      "explanation": "The method concatenates user‑supplied filter strings directly into a SOQL WHERE clause without any allow‑list or escaping, allowing a malicious caller to inject arbitrary conditions and potentially expose data beyond intended filters.",
      "remediation": "Replace the dynamic string construction with bind variables or a whitelist of allowed fields. For example, parse each filter into a field and value pair, validate the field against an allow‑list, and build the query using bind variables or Database.queryWithBinds."
    }
  ]
}

