{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security Violation",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4-6",
      "explanation": "The method queries Contact records for fields (Name, Email, Birthdate) that the user does not have read access to per the permission set, and then returns the entire record. This exposes sensitive data and violates FLS.",
      "remediation": "Restrict the SOQL to only fields the user can read (e.g., SELECT Id, Phone FROM Contact WHERE Id = :contactId) or use Security.stripInaccessible to remove inaccessible fields before returning. Additionally, enforce CRUD/FLS checks with Security.isReadAllowed/stripInaccessible or @AuraEnabled methods that respect user permissions."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violation: AnnualRevenue read without permission",
      "severity": "High",
      "file": "AccountRatingService.cls",
      "lines": "6-7",
      "explanation": "The method queries the AnnualRevenue field, which the user may not have read permission for, and then updates Rating. This bypasses field-level security and exposes sensitive data.",
      "remediation": "Enforce FLS by using Security.stripInaccessible, WITH USER_MODE, or checking field permissions before the query. Ensure the query only selects fields the user is allowed to read."
    },
    {
      "category": "C4",
      "title": "Permission set grants class access exposing hidden field",
      "severity": "Medium",
      "file": "Account_Rating_Editor.permissionset-meta.xml",
      "lines": "classAccesses",
      "explanation": "The permission set allows the AccountRatingService class, which reads AnnualRevenue, but the role is intended to be hidden from that field. This grants excessive permissions beyond the described purpose.",
      "remediation": "Remove the class access from the permission set or modify the class so it does not read AnnualRevenue. Alternatively, adjust the permission set to reflect the actual permissions needed."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Unprotected Task creation without FLS check",
      "severity": "Medium",
      "file": "CaseEscalationService.cls",
      "lines": "17",
      "explanation": "The method creates a Task record without verifying that the running user has create permission or that the fields are accessible. The permission set for support agents does not grant Task creation, so the DML will fail and the exception is swallowed, hiding the violation and causing silent failures.",
      "remediation": "Add an FLS check before the insert, e.g., if (!Task.isCreateable() || !Security.stripInaccessible(Task.sObjectType, new List<Task>{t}, Schema.OperationsEnum.CREATE).isEmpty()) { /* handle error */ } and remove the silent catch. Alternatively, grant create permission on Task to the permission set if task creation is intended."
    }
  ]
}

