{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Sharing rules bypassed in @AuraEnabled method",
      "severity": "High",
      "file": "FinancialDashboardController.cls",
      "lines": "7",
      "explanation": "The class is declared without sharing and the @AuraEnabled method is reachable by partner community users. The query uses WITH USER_MODE, which enforces CRUD/FLS but not sharing, allowing users to see all Opportunity records regardless of sharing rules.",
      "remediation": "Declare the class with 'with sharing' or 'inherited sharing', or add WITH SECURITY_ENFORCED to the SOQL query to enforce sharing. Ensure that only records the user is allowed to see are returned."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing not enforced in Aura-enabled method",
      "severity": "Medium",
      "file": "DataAggregator.cls",
      "lines": "16-18",
      "explanation": "The @AuraEnabled method runs in a class declared without sharing, so sharing rules are ignored. The query uses WITH USER_MODE, which only enforces CRUD/FLS, not sharing, allowing users to view leads they should not have access to.",
      "remediation": "Declare the class with sharing (or inherited sharing) or use WITH SECURITY_ENFORCED in the SOQL. Ensure that any Aura-enabled entry point runs in a sharing context so that record-level access is respected."
    }
  ]
}

