{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Permissions in Permission Set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants ModifyAllData and ViewAllData, which allow users to read and modify all records in the org. This is far beyond the described purpose of viewing and closing cases, creating a privilege escalation risk for internal users.",
      "remediation": "Remove the ModifyAllData and ViewAllData permissions from the permission set. Grant only the necessary CRUD permissions on the Case object (Read, Edit, and Close) and remove AuthorApex unless the class contains Apex that must be authored by the user."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive System Permission in Permission Set",
      "severity": "Medium",
      "file": "Accounts_Payable_Clerk.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants the ManageInternalUsers permission, which allows users to manage internal user accounts. This permission is not required for reviewing or approving invoices and provides unnecessary elevated privileges.",
      "remediation": "Remove the ManageInternalUsers permission from the permission set or replace it with a more restrictive permission that is actually needed for the clerk’s tasks."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive ViewAllData permission",
      "severity": "High",
      "file": "Report_Viewer_Plus.permissionset-meta.xml",
      "lines": "userPermissions[ViewAllData]",
      "explanation": "The permission set grants the ViewAllData permission, which allows users to view all data in the org. This exceeds the described purpose of the permission set, which is only to view and export operational reports, and introduces a privilege escalation risk for internal users.",
      "remediation": "Remove the ViewAllData permission from the permission set or replace it with a more restrictive set of permissions that align with the intended use. If broader data access is truly required, document the justification and limit the permission set to only the necessary objects and fields."
    }
  ]
}

